(async function(){
    for (let i=0;i<15;i++){ if (document.readyState==='complete') break; await new Promise(r=>setTimeout(r,1500)); }
    const d = document;
    const out = { href: location.href, title: d.title, ready: d.readyState };
    out.forms = [];
    d.querySelectorAll('form').forEach(f => {
      const fid = { id: f.id || null, action: f.action, method: f.method, name: f.name || null, inputs: [] };
      f.querySelectorAll('input, select, textarea, button').forEach(el => {
        fid.inputs.push({
          tag: el.tagName, type: el.type || null, name: el.name || null, id: el.id || null,
          cls: String(el.className||'').slice(0,60),
          value: (el.type==='checkbox'||el.type==='radio') ? String(el.checked) : (el.value || '').slice(0,100),
          options: el.tagName==='SELECT' ? Array.from(el.options).map(o=>o.value+':'+o.textContent.trim()).slice(0,80) : undefined,
          placeholder: el.placeholder || undefined, max: el.maxLength || undefined
        });
      });
      out.forms.push(fid);
    });
    out.headings = [];
    d.querySelectorAll('h1,h2,h3,h4,.block-title,.sec-title,dt').forEach(el => {
      const t = (el.textContent||'').trim().replace(/\s+/g,' ').slice(0,50);
      if (t && t.length > 1) out.headings.push(t);
    });
    out.headings = out.headings.slice(0, 60);
    out.btns = [];
    d.querySelectorAll('input[type=submit], input[type=button], button, .greenButton, a.btn').forEach(el => {
      const t = (el.value || el.textContent || '').trim().slice(0,30);
      out.btns.push({ text: t, tag: el.tagName, type: el.type||null, name: el.name||null, id: el.id||null, cls: String(el.className||'').slice(0,60), href: el.getAttribute && el.getAttribute('href') });
    });
    out.btns = out.btns.slice(0, 40);
    return JSON.stringify(out);
  })()
